/bin/bash -lc "python - <<'PY'
import urllib.request
for url in ['https://developers.openai.com/api/reference/resources/responses/methods/create','https://developers.openai.com/api/docs/guides/your-data']:
    try:
        with urllib.request.urlopen(url, timeout=25) as r:
            html=r.read().decode()
        from html.parser import HTMLParser
        class Text(HTMLParser):
            def handle_data(self,data):
                s=data.strip()
                if s: parts.append(s)
        parts=[]
        Text().feed(html)
        print(url)
        for i,p in enumerate(parts):
            if any(w in p.lower() for w in ('store', 'output_text', 'retention','input', 'authorization')):
                print(' '.join(parts[max(0,i-1):i+3])[:900])
    except Exception as exc:
        print(type(exc).__name__)
PY"

